script:
// Chip (ds-metrics §4 — FilterChip .filled): capsule 35 high, padding h md, bodyMedium; selected = accentPrimary fill +
// onAccent text, otherwise solidChromeSurface + el16. Selection is owned by the screen:
//   {"type": "Chip", "repeat": {"over": "plans"}, "props": {"title": "=item.title", "selected": "=plan == item.id"},
//    "on": {"tap": "plan = item.id"}}
param title: string
param selected: bool = false
param icon: icon? = null
event tap
let ink = selected ? @color.onAccent : @color.el16
